31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    @Email
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    public String getAddress() {
69	        return this.address;
70	    }
71	
72	    public void setAddress(String address) {
73	        this.address = address;
74	    }
75	
76	    public String getCity() {
77	        return this.city;
78	    }
79	
80	    public void setCity(String city) {
81	        this.city = city;
82	    }
83	
84	    public String getTelephone() {
85	        return this.telephone;
86	    }
87	
88	    public void setTelephone(String telephone) {
89	        this.telephone = telephone;
90	    }
91	
92	    public String getEmail() {
93	        return this.email;
94	    }
95	
96	    public void setEmail(String email) {
97	        this.email = normalizeEmail(email);
98	    }
99	
100	    public LocalDate getRegistrationDate() {
101	        return this.registrationDate;
102	    }
103	
104	    public void setRegistrationDate(LocalDate registrationDate) {
105	        this.registrationDate = registrationDate;
106	    }
107	
108	    public String getCustomerCode() {
109	        return this.customerCode;
110	    }
111	
112	    public void setCustomerCode(String customerCode) {
113	        this.customerCode = customerCode;
114	    }
115	
116	    /**
117	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
118	     * source of truth for how an email is persisted, so inputs that differ only in letter case
119	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
120	     * (create and update, mapper or hand-copied) stores the same canonical value.
121	     *
122	     * @param email the raw email, possibly {@code null}
123	     * @return the lower-cased form, or {@code null} if the input was {@code null}
124	     */
125	    public static String normalizeEmail(String email) {
126	        return email == null ? null : email.toLowerCase();
127	    }
128	
129	    /**
130	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
131	     * truth for how a telephone is compared and persisted, so inputs that differ only in
132	     * formatting (spaces, dashes, brackets) are treated as the same number.
133	     *
134	     * <p>The rules are:
135	     * <ul>
136	     *   <li>spaces, dashes and brackets are stripped;</li>
137	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
138	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
139	     *       is dropped from the national digits;</li>
140	     *   <li>the result must have 8 to 15 digits after the {@code '+'}.</li>
141	     * </ul>
142	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
143	     * values are returned unchanged.
144	     *
145	     * @param telephone the raw telephone, possibly {@code null}
146	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
147	     *     valid E.164 number
148	     */
149	    public static String normalizeTelephone(String telephone) {
150	        if (telephone == null) {
151	            return null;
152	        }
153	        String trimmed = telephone.trim();
154	        boolean hasCountryCode = trimmed.startsWith("+");
155	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
156	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
157	        if (hasCountryCode) {
158	            stripped = stripped.substring(1);
159	        }
160	        if (!stripped.matches("\\d+")) {
161	            return null;
162	        }
163	        String digits;
164	        if (hasCountryCode) {
165	            digits = stripped;
166	        } else {
167	            if (stripped.startsWith("0")) {
168	                stripped = stripped.substring(1);
169	            }
170	            digits = "61" + stripped;
171	        }
172	        if (digits.length() < 8 || digits.length() > 15) {
173	            return null;
174	        }
175	        return "+" + digits;
176	    }
177	
178	    /**
179	     * Normalize a household field (such as last name or address) to its canonical form for
180	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
181	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
182	     * that differ only in letter case or spacing are treated as the same value.
183	     *
184	     * @param value the raw field value, possibly {@code null}
185	     * @return the normalized form, or {@code null} if the input was {@code null}
186	     */
187	    public static String normalizeHousehold(String value) {
188	        if (value == null) {
189	            return null;
190	        }
191	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
192	    }
193	
194	    /**
195	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
196	     * last name and address compared case-insensitively with collapsed whitespace (see
197	     * {@link #normalizeHousehold(String)}). The value is deterministic in those two fields, so two
198	     * owners who share a household are assigned the same id. It is formatted {@code 'HH-<HEX12>'}
199	     * where {@code HEX12} is the first twelve upper-cased hex characters of the SHA-256 digest of
200	     * the normalized last name and address.
201	     *
202	     * @param lastName the owner's last name, possibly {@code null}
203	     * @param address the owner's address, possibly {@code null}
204	     * @return the household id, or {@code null} if either field is {@code null}
205	     */
206	    public static String householdId(String lastName, String address) {
207	        String normalizedLastName = normalizeHousehold(lastName);
208	        String normalizedAddress = normalizeHousehold(address);
209	        if (normalizedLastName == null || normalizedAddress == null) {
210	            return null;
211	        }
212	        String key = normalizedLastName + "\n" + normalizedAddress;
213	        try {
214	            byte[] digest = MessageDigest.getInstance("SHA-256")
215	                .digest(key.getBytes(StandardCharsets.UTF_8));
216	            StringBuilder hex = new StringBuilder(digest.length * 2);
217	            for (byte b : digest) {
218	                hex.append(String.format("%02x", b));
219	            }
220	            return "HH-" + hex.substring(0, 12).toUpperCase();
221	        } catch (NoSuchAlgorithmException e) {
222	            // SHA-256 is a standard algorithm required to be present on every JVM.
223	            throw new IllegalStateException("SHA-256 not available", e);
224	        }
225	    }
226	
227	    protected Set<Pet> getPetsInternal() {
228	        if (this.pets == null) {
229	            this.pets = new HashSet<>();
230	        }
231	        return this.pets;
232	    }
233	
234	    protected void setPetsInternal(Set<Pet> pets) {
235	        this.pets = pets;
236	    }
237	
238	    public List<Pet> getPets() {
239	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
240	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
241	        return Collections.unmodifiableList(sortedPets);
242	    }
243	
244	    public void setPets(List<Pet> pets) {
245	        this.pets = new HashSet<>(pets);
246	    }
247	
248	    public void addPet(Pet pet) {
249	        getPetsInternal().add(pet);
250	        pet.setOwner(this);
251	    }
252	
253	    /**
254	     * Return the Pet with the given name, or null if none found for this Owner.
255	     *
256	     * @param name to test
257	     * @return true if pet name is already in use
258	     */
259	    public Pet getPet(String name) {
260	        return getPet(name, false);
261	    }
262	
263	    /**
264	     * Return the Pet with the given name, or null if none found for this Owner.
265	     *
266	     * @param name to test
267	     * @return true if pet name is already in use
268	     */
269	    public Pet getPet(String name, boolean ignoreNew) {
270	        name = name.toLowerCase();
271	        for (Pet pet : getPetsInternal()) {
272	            if (!ignoreNew || !pet.isNew()) {
273	                String compName = pet.getName();
274	                compName = compName.toLowerCase();
275	                if (compName.equals(name)) {
276	                    return pet;
277	                }
278	            }
279	        }
280	        return null;
281	    }
282	
283	    public Pet getPet(Integer petId) {
284	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
285	    }
286	
287	    @Override
288	    public String toString() {
289	        return new ToStringCreator(this)
290	
291	            .append("id", this.getId())
292	            .append("new", this.isNew())
293	            .append("lastName", this.getLastName())
294	            .append("firstName", this.getFirstName())
295	            .append("address", this.address)
296	            .append("city", this.city)
297	            .append("telephone", this.telephone)
298	            .toString();
299	    }
300	}
