35	/**
36	 * Mostly used as a facade for all Petclinic controllers
37	 * Also a placeholder for @Transactional and @Cacheable annotations
38	 *
39	 * @author Michael Isvy
40	 * @author Vitaliy Fedoriv
41	 */
42	@Service
43	public class ClinicServiceImpl implements ClinicService {
44	
45	    private final PetRepository petRepository;
46	    private final VetRepository vetRepository;
47	    private final OwnerRepository ownerRepository;
48	    private final VisitRepository visitRepository;
49	    private final SpecialtyRepository specialtyRepository;
50	    private final PetTypeRepository petTypeRepository;
51	
52	    public ClinicServiceImpl(
53	        PetRepository petRepository,
54	        VetRepository vetRepository,
55	        OwnerRepository ownerRepository,
56	        VisitRepository visitRepository,
57	        SpecialtyRepository specialtyRepository,
58	        PetTypeRepository petTypeRepository) {
59	        this.petRepository = petRepository;
60	        this.vetRepository = vetRepository;
61	        this.ownerRepository = ownerRepository;
62	        this.visitRepository = visitRepository;
63	        this.specialtyRepository = specialtyRepository;
64	        this.petTypeRepository = petTypeRepository;
65	    }
66	
67	    @Override
68	    @Transactional(readOnly = true)
69	    public Collection<Pet> findAllPets() throws DataAccessException {
70	        return petRepository.findAll();
71	    }
72	
73	    @Override
74	    @Transactional(readOnly = true)
75	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
76	        return petRepository.findAll(pageable);
77	    }
78	
79	    @Override
80	    @Transactional
81	    public void deletePet(Pet pet) throws DataAccessException {
82	        petRepository.delete(pet);
83	    }
84	
85	    @Override
86	    @Transactional(readOnly = true)
87	    public Visit findVisitById(int visitId) throws DataAccessException {
88	        return findEntityById(() -> visitRepository.findById(visitId));
89	    }
90	
91	    @Override
92	    @Transactional(readOnly = true)
93	    public Collection<Visit> findAllVisits() throws DataAccessException {
94	        return visitRepository.findAll();
95	    }
96	
97	    @Override
98	    @Transactional
99	    public void deleteVisit(Visit visit) throws DataAccessException {
100	        visitRepository.delete(visit);
101	    }
102	
103	    @Override
104	    @Transactional(readOnly = true)
105	    public Vet findVetById(int id) throws DataAccessException {
106	        return findEntityById(() -> vetRepository.findById(id));
107	    }
108	
109	    @Override
110	    @Transactional(readOnly = true)
111	    public Collection<Vet> findAllVets() throws DataAccessException {
112	        return vetRepository.findAll();
113	    }
114	
115	    @Override
116	    @Transactional
117	    public void saveVet(Vet vet) throws DataAccessException {
118	        vetRepository.save(vet);
119	    }
120	
121	    @Override
122	    @Transactional
123	    public void deleteVet(Vet vet) throws DataAccessException {
124	        vetRepository.delete(vet);
125	    }
126	
127	    @Override
128	    @Transactional(readOnly = true)
129	    public Collection<Owner> findAllOwners() throws DataAccessException {
130	        return ownerRepository.findAll();
